export class SettlementStore {
    private readonly batches = new Map<string,SettlementBatch>();
    private readonly orders = new Map<string,string>();

    create(batch: SettlementBatch): SettlementBatch {
        if (this.batches.has(batch.id)) {
            throw new Error('Settlement already exists');
        }
        for (const line of batch.lines) {
            if (this.orders.has(line.orderId)) {
                throw new Error('Order has already entered a settlement');
            }
        }
        this.batches.set(batch.id,copyBatch(batch));
        for (const line of batch.lines) {
            this.orders.set(line.orderId,batch.id);
        }
        return copyBatch(batch);
    }

    get(id: string): SettlementBatch | undefined {
        const value = this.batches.get(id);
        return value && copyBatch(value);
    }

    update(batch: SettlementBatch): SettlementBatch {
        const current = this.batches.get(batch.id);
        if (!current) {
            throw new Error('Settlement not found');
        }
        if (current.accountId !== batch.accountId || JSON.stringify(current.lines) !== JSON.stringify(batch.lines)) {
            throw new Error('Settlement financial lines are immutable');
        }
        this.batches.set(batch.id,copyBatch(batch));
        return copyBatch(batch);
    }

    list(accountId?: string): SettlementBatch[] {
        return [...this.batches.values()]
            .filter(batch=>accountId===undefined || batch.accountId===accountId)
            .sort((left,right)=>right.createdAt-left.createdAt || left.id.localeCompare(right.id))
            .map(copyBatch);
    }

    forOrder(orderId: string): SettlementBatch | undefined {
        const id = this.orders.get(orderId);
        return id === undefined ? undefined : this.get(id);
    }
}

prepare(accountId: string, orders: Order[], feeBasisPoints: number): SettlementBatch {
        const lines = orders.map(order=>settlementLine(order,feeBasisPoints));
        const batch = createSettlement(this.makeId(),accountId,lines,this.now());
        return this.store.create(batch);
    }

approve(id: string, memberId: string): SettlementBatch {
        const batch = approveSettlement(this.get(id),memberId,this.now());
        return this.store.update(batch);
    }

export function calculateFee(amount: Money, basisPoints: number): Money {
    if (!Number.isInteger(basisPoints) || basisPoints < 0 || basisPoints > 10000) {
        throw new Error('Fee basis points must be between zero and ten thousand');
    }
    return Money.fromCents(Math.round(amount.cents * basisPoints / 10000));
}

export function settlementLine(order: Order, basisPoints: number): SettlementLine {
    if (!['paid', 'partially-refunded', 'refunded'].includes(order.status)) {
        throw new Error('Only paid orders can settle');
    }
    const total = orderTotal(order);
    const refunded = refundTotal(order);
    const net = total.subtract(refunded);
    const fee = calculateFee(net,basisPoints);
    return {
        orderId: order.id,
        memberId: order.memberId,
        grossCents: total.cents,
        refundedCents: refunded.cents,
        feeCents: fee.cents,
        payableCents: net.subtract(fee).cents,
        currency: 'CNY',
    };
}

export function createSettlement(id: string, accountId: string, lines: SettlementLine[], now: number): SettlementBatch {
    if (!id || !accountId || lines.length === 0) {
        throw new Error('Settlement identifiers and lines are required');
    }
    if (new Set(lines.map(line=>line.orderId)).size !== lines.length) {
        throw new Error('Settlement contains duplicate orders');
    }
    return {
        id,
        accountId,
        state: 'draft',
        lines: lines.map(line=>({...line})),
        createdAt: now,
    };
}

export function approveSettlement(batch: SettlementBatch, memberId: string, now: number): SettlementBatch {
    if (batch.state !== 'draft' || !memberId) {
        throw new Error('Settlement cannot be approved');
    }
    return {
        ...batch,
        state: 'approved',
        approvedBy: memberId,
        approvedAt: now,
    };
}

create(batch: SettlementBatch): SettlementBatch {
        if (this.batches.has(batch.id)) {
            throw new Error('Settlement already exists');
        }
        for (const line of batch.lines) {
            if (this.orders.has(line.orderId)) {
                throw new Error('Order has already entered a settlement');
            }
        }
        this.batches.set(batch.id,copyBatch(batch));
        for (const line of batch.lines) {
            this.orders.set(line.orderId,batch.id);
        }
        return copyBatch(batch);
    }

export function reserveStock(item: StockItem, amount: number, now: number): StockItem {
    quantity(amount);
    if (amount > item.available) {
        throw new DomainError(ERROR_CODES.FORBIDDEN, 'Insufficient stock');
    }
    return {
        ...item,
        available: item.available - amount,
        reserved: item.reserved + amount,
        version: item.version + 1,
        updatedAt: now,
    };
}

export function releaseStock(item: StockItem, amount: number, now: number): StockItem {
    quantity(amount);
    if (amount > item.reserved) {
        throw new Error('Cannot release unreserved stock');
    }
    return {
        ...item,
        available: item.available + amount,
        reserved: item.reserved - amount,
        version: item.version + 1,
        updatedAt: now,
    };
}

export function consumeStock(item: StockItem, amount: number, now: number): StockItem {
    quantity(amount);
    if (amount > item.reserved) {
        throw new Error('Cannot consume unreserved stock');
    }
    return {
        ...item,
        reserved: item.reserved - amount,
        version: item.version + 1,
        updatedAt: now,
    };
}

export function receiveStock(item: StockItem, amount: number, now: number): StockItem {
    quantity(amount);
    const available = item.available + amount;
    if (!Number.isSafeInteger(available)) {
        throw new Error('Stock exceeds safe integer range');
    }
    return {
        ...item,
        available,
        version: item.version + 1,
        updatedAt: now,
    };
}

export function changeReservation(current: Reservation, state: Reservation['state'], now: number): Reservation {
    if (current.state !== 'active') {
        throw new Error('Reservation has already completed');
    }
    if (state === 'active') {
        throw new Error('Reservation must move to a completed state');
    }
    return { ...current, state, updatedAt: now };
}

export interface StockItem {
    sku: string;
    warehouseId: string;
    available: number;
    reserved: number;
    version: number;
    updatedAt: number;
}

get(id: string): SettlementBatch | undefined {
        const value = this.batches.get(id);
        return value && copyBatch(value);
    }

export class Money {
    readonly cents: number;
    constructor(cents: number) {
        if (!Number.isInteger(cents)) throw new Error('Money must use integer cents');
        if (cents < 0) throw new Error('Money cannot be negative');
        this.cents = cents;
    }
    static fromMajor(value: number): Money {
        if (!Number.isFinite(value)) throw new Error('Invalid money value');
        return new Money(Math.round(value * 100));
    }
    static fromCents(value: number): Money { return new Money(value); }
    add(other: Money): Money { return new Money(this.cents + other.cents); }
    subtract(other: Money): Money { return new Money(this.cents - other.cents); }
    multiply(count: number): Money { return new Money(Math.round(this.cents * count)); }
    greaterThan(other: Money): boolean { return this.cents > other.cents; }
    greaterThanOrEqual(other: Money): boolean { return this.cents >= other.cents; }
    equals(other: Money): boolean { return this.cents === other.cents; }
    toMajor(): number { return this.cents / 100; }
    toJSON(): { cents: number } { return { cents: this.cents }; }
}

static fromMajor(value: number): Money {
        if (!Number.isFinite(value)) throw new Error('Invalid money value');
        return new Money(Math.round(value * 100));
    }

export function paySettlement(batch: SettlementBatch, reference: string, now: number): SettlementBatch {
    if (batch.state !== 'approved' || !reference.trim()) {
        throw new Error('Settlement cannot be paid');
    }
    return {
        ...batch,
        state: 'paid',
        bankReference: reference,
        paidAt: now,
    };
}

export function settlementTotal(batch: SettlementBatch): Money {
    return batch.lines.reduce((sum,line)=>sum.add(Money.fromCents(line.payableCents)),Money.fromCents(0));
}

export function discountLine(amount: Money, percent: number): Money {
    if (!Number.isFinite(percent) || percent < 0 || percent > 100) {
        throw new Error('Discount percentage is invalid');
    }
    return Money.fromCents(Math.round(amount.cents * percent / 100));
}

export function discountOrder(order: Order, percent: number): Money {
    return order.lines.reduce((sum,line)=>sum.add(discountLine(line.unitPrice.multiply(line.quantity),percent)),Money.fromCents(0));
}

export interface SettlementLine {
    orderId: string;
    memberId: string;
    grossCents: number;
    refundedCents: number;
    feeCents: number;
    payableCents: number;
    currency: 'CNY';
}

export interface SettlementBatch {
    id: string;
    accountId: string;
    state: 'draft' | 'approved' | 'paid';
    lines: SettlementLine[];
    createdAt: number;
    approvedBy?: string;
    approvedAt?: number;
    paidAt?: number;
    bankReference?: string;
}

