export class ReportService {
    orderRevenue(orders: Order[]): number { return orders.reduce((sum, order) => sum + orderTotal(order).cents - refundTotal(order).cents, 0); }
    invoiceRevenue(invoices: Invoice[]): number { return invoices.filter(invoice => invoice.status === 'paid').reduce((sum, invoice) => sum + invoiceTotal(invoice).cents, 0); }
    groupOrders(orders: Order[]): Map<string, Order[]> { const groups = new Map<string, Order[]>(); for (const order of orders) groups.set(order.memberId, [...(groups.get(order.memberId) ?? []), order]); return groups; }
    statusCounts(orders: Order[]): Record<string, number> { return orders.reduce((result, order) => ({ ...result, [order.status]: (result[order.status] ?? 0) + 1 }), {}); }
    dateRange(orders: Order[], from: number, to: number): Order[] { return orders.filter(order => order.createdAt >= from && order.createdAt <= to); }
    topMembers(orders: Order[], limit: number): string[] { return [...this.groupOrders(orders).entries()].sort((a, b) => b[1].length - a[1].length).slice(0, limit).map(([member]) => member); }
}

