get(id: string): SettlementBatch | undefined {
        const value = this.batches.get(id);
        return value && copyBatch(value);
    }

update(batch: SettlementBatch): SettlementBatch {
        const current = this.batches.get(batch.id);
        if (!current) {
            throw new Error('Settlement not found');
        }
        if (current.accountId !== batch.accountId || JSON.stringify(current.lines) !== JSON.stringify(batch.lines)) {
            throw new Error('Settlement financial lines are immutable');
        }
        this.batches.set(batch.id,copyBatch(batch));
        return copyBatch(batch);
    }

list(accountId?: string): SettlementBatch[] {
        return [...this.batches.values()]
            .filter(batch=>accountId===undefined || batch.accountId===accountId)
            .sort((left,right)=>right.createdAt-left.createdAt || left.id.localeCompare(right.id))
            .map(copyBatch);
    }

forOrder(orderId: string): SettlementBatch | undefined {
        const id = this.orders.get(orderId);
        return id === undefined ? undefined : this.get(id);
    }

export interface Reservation {
    id: string;
    orderId: string;
    warehouseId: string;
    sku: string;
    quantity: number;
    state: 'active' | 'released' | 'consumed';
    createdAt: number;
    updatedAt: number;
}

export function stockKey(warehouseId: string, sku: string): string {
    if (!warehouseId.trim() || !sku.trim()) {
        throw new Error('Warehouse and SKU are required');
    }
    return JSON.stringify([warehouseId, sku]);
}

export function quantity(value: number): number {
    if (!Number.isSafeInteger(value) || value <= 0) {
        throw new Error('Quantity must be a positive safe integer');
    }
    return value;
}

export function createStock(sku: string, warehouseId: string, amount: number, now: number): StockItem {
    stockKey(warehouseId, sku);
    if (!Number.isSafeInteger(amount) || amount < 0) {
        throw new Error('Initial stock must be a nonnegative safe integer');
    }
    return {
        sku,
        warehouseId,
        available: amount,
        reserved: 0,
        version: 1,
        updatedAt: now,
    };
}

function filters(input: Record<string,unknown>): OrderFilters {
    const result: OrderFilters = {};
    const memberId = optionalString(input.memberId,'memberId');
    if (memberId !== undefined) {
        result.memberId = memberId;
    }
    const status = optionalString(input.status,'status');
    if (status !== undefined) {
        if (!['draft','paid','partially-refunded','refunded','cancelled'].includes(status)) {
            throw new Error('Unknown order status');
        }
        result.status = status as OrderFilters['status'];
    }
    if (input.from !== undefined) {
        result.from = integerInput(input.from,'from');
    }
    if (input.to !== undefined) {
        result.to = integerInput(input.to,'to');
    }
    if (result.from !== undefined && result.to !== undefined && result.from > result.to) {
        throw new Error('Order interval is invalid');
    }
    return result;
}

