export function consumeStock(item: StockItem, amount: number, now: number): StockItem {
    quantity(amount);
    if (amount > item.reserved) {
        throw new Error('Cannot consume unreserved stock');
    }
    return {
        ...item,
        reserved: item.reserved - amount,
        version: item.version + 1,
        updatedAt: now,
    };
}

export function receiveStock(item: StockItem, amount: number, now: number): StockItem {
    quantity(amount);
    const available = item.available + amount;
    if (!Number.isSafeInteger(available)) {
        throw new Error('Stock exceeds safe integer range');
    }
    return {
        ...item,
        available,
        version: item.version + 1,
        updatedAt: now,
    };
}

export function changeReservation(current: Reservation, state: Reservation['state'], now: number): Reservation {
    if (current.state !== 'active') {
        throw new Error('Reservation has already completed');
    }
    if (state === 'active') {
        throw new Error('Reservation must move to a completed state');
    }
    return { ...current, state, updatedAt: now };
}

