export class MemoryChannel implements Channel {
    readonly kind: NotificationKind;
    readonly messages: Array<{ recipient: string; subject: string; body: string }> = [];
    constructor(kind: NotificationKind) { this.kind = kind; }
    async send(recipient: string, subject: string, body: string): Promise<void> { this.messages.push({ recipient, subject, body }); }
    count(): number { return this.messages.length; }
    latest(): { recipient: string; subject: string; body: string } | undefined { return this.messages[this.messages.length - 1]; }
    clear(): void { this.messages.length = 0; }
}

function copyMessage(message: OutboxMessage): OutboxMessage {
    return {...message,data:{...message.data}};
}

get(id: string): OutboxMessage {
        const value = this.values.get(id);
        if (!value) {
            throw new Error('Outbox message not found');
        }
        return copyMessage(value);
    }

due(now: number, limit: number): OutboxMessage[] {
        if (!Number.isInteger(limit) || limit < 1) {
            throw new Error('Outbox limit must be positive');
        }
        return [...this.values.values()]
            .filter(value=>value.state==='pending' && value.nextAttemptAt<=now)
            .sort((left,right)=>left.nextAttemptAt-right.nextAttemptAt || left.id.localeCompare(right.id))
            .slice(0,limit)
            .map(copyMessage);
    }

claim(id: string, now: number): OutboxMessage {
        const value = this.get(id);
        if (value.state !== 'pending' || value.nextAttemptAt > now) {
            throw new Error('Outbox message is not ready');
        }
        const claimed: OutboxMessage = {
            ...value,
            state:'delivering',
            attempts:value.attempts+1,
        };
        this.values.set(id,claimed);
        return copyMessage(claimed);
    }

complete(id: string, now: number): OutboxMessage {
        const value = this.get(id);
        if (value.state !== 'delivering') {
            throw new Error('Outbox message is not being delivered');
        }
        const completed: OutboxMessage = {
            ...value,
            state:'delivered',
            deliveredAt:now,
            lastError:undefined,
        };
        this.values.set(id,completed);
        return copyMessage(completed);
    }

fail(id: string, error: string, retryAt: number, maxAttempts: number): OutboxMessage {
        const value = this.get(id);
        if (value.state !== 'delivering' || !Number.isInteger(maxAttempts) || maxAttempts<1) {
            throw new Error('Outbox failure transition is invalid');
        }
        const failed: OutboxMessage = {
            ...value,
            state:value.attempts>=maxAttempts ? 'failed' : 'pending',
            nextAttemptAt:retryAt,
            lastError:error,
        };
        this.values.set(id,failed);
        return copyMessage(failed);
    }

list(state?: OutboxMessage['state']): OutboxMessage[] {
        return [...this.values.values()]
            .filter(value=>state===undefined || value.state===state)
            .map(copyMessage);
    }

record(action: string, actorId: string, payload: Record<string, unknown>): AuditEntry {
        if (!action.trim() || !actorId.trim()) {
            throw new Error('Audit action and actor are required');
        }
        const entry = safeAudit({
            id: this.id(),
            action,
            actorId,
            payload,
            createdAt: this.now(),
        });
        return this.store.append(entry);
    }

list(query: AuditQuery = {}): AuditEntry[] {
        if (query.from !== undefined && query.to !== undefined && query.from > query.to) {
            throw new Error('Audit interval is invalid');
        }
        return this.store.all().filter(entry => {
            if (query.action !== undefined && query.action !== entry.action) return false;
            if (query.actorId !== undefined && query.actorId !== entry.actorId) return false;
            if (query.from !== undefined && entry.createdAt < query.from) return false;
            if (query.to !== undefined && entry.createdAt > query.to) return false;
            return true;
        });
    }

topics(query: AuditQuery = {}): string[] {
        return [...new Set(this.list(query).map(entry => auditTopic(entry.action)))].sort();
    }

statistics(query: AuditQuery = {}): { count: number; actors: number; actions: Record<string, number> } {
        const entries = this.list(query);
        const actions: Record<string, number> = {};
        for (const entry of entries) {
            actions[entry.action] = (actions[entry.action] ?? 0) + 1;
        }
        return {
            count: entries.length,
            actors: new Set(entries.map(entry => entry.actorId)).size,
            actions,
        };
    }

export interface AuditQuery {
    action?: string;
    actorId?: string;
    from?: number;
    to?: number;
}

export class AuditService {
    private readonly store: AuditStore;
    private readonly now: () => number;
    private readonly id: () => string;

    constructor(store: AuditStore, id: () => string, now = () => Date.now()) {
        this.store = store;
        this.id = id;
        this.now = now;
    }

    record(action: string, actorId: string, payload: Record<string, unknown>): AuditEntry {
        if (!action.trim() || !actorId.trim()) {
            throw new Error('Audit action and actor are required');
        }
        const entry = safeAudit({
            id: this.id(),
            action,
            actorId,
            payload,
            createdAt: this.now(),
        });
        return this.store.append(entry);
    }

    list(query: AuditQuery = {}): AuditEntry[] {
        if (query.from !== undefined && query.to !== undefined && query.from > query.to) {
            throw new Error('Audit interval is invalid');
        }
        return this.store.all().filter(entry => {
            if (query.action !== undefined && query.action !== entry.action) return false;
            if (query.actorId !== undefined && query.actorId !== entry.actorId) return false;
            if (query.from !== undefined && entry.createdAt < query.from) return false;
            if (query.to !== undefined && entry.createdAt > query.to) return false;
            return true;
        });
    }

    topics(query: AuditQuery = {}): string[] {
        return [...new Set(this.list(query).map(entry => auditTopic(entry.action)))].sort();
    }

    statistics(query: AuditQuery = {}): { count: number; actors: number; actions: Record<string, number> } {
        const entries = this.list(query);
        const actions: Record<string, number> = {};
        for (const entry of entries) {
            actions[entry.action] = (actions[entry.action] ?? 0) + 1;
        }
        return {
            count: entries.length,
            actors: new Set(entries.map(entry => entry.actorId)).size,
            actions,
        };
    }
}

export interface DeliveryReceipt {
    messageId: string;
    recipient: string;
    deliveredAt: number;
    attempts: number;
}

export interface DeliveryFailure {
    messageId: string;
    reason: string;
    nextAttemptAt: number;
    exhausted: boolean;
}

export interface DeliveryPolicy {
    maxAttempts: number;
    initialDelay: number;
    maximumDelay: number;
    batchSize: number;
}

ready(): OutboxMessage[] {
        return this.outbox.due(this.now(),this.policy.batchSize);
    }

begin(id: string): OutboxMessage {
        return this.outbox.claim(id,this.now());
    }

succeed(id: string): DeliveryReceipt {
        const message = this.outbox.complete(id,this.now());
        return {
            messageId:message.id,
            recipient:message.recipient,
            deliveredAt:message.deliveredAt!,
            attempts:message.attempts,
        };
    }

reject(id: string, reason: string): DeliveryFailure {
        if (!reason.trim()) {
            throw new Error('Delivery failure requires a reason');
        }
        const current = this.outbox.get(id);
        const delay = Math.min(this.policy.maximumDelay,this.policy.initialDelay * 2 ** (current.attempts - 1));
        const failed = this.outbox.fail(id,reason,this.now()+delay,this.policy.maxAttempts);
        return {
            messageId:id,
            reason,
            nextAttemptAt:failed.nextAttemptAt,
            exhausted:failed.state === 'failed',
        };
    }

receipts(recipient?: string): DeliveryReceipt[] {
        return this.outbox.list('delivered')
            .filter(message=>recipient===undefined || message.recipient===recipient)
            .map(message=>({
                messageId:message.id,
                recipient:message.recipient,
                deliveredAt:message.deliveredAt!,
                attempts:message.attempts,
            }));
    }

