export class SettlementStore {
    private readonly batches = new Map<string,SettlementBatch>();
    private readonly orders = new Map<string,string>();

    create(batch: SettlementBatch): SettlementBatch {
        if (this.batches.has(batch.id)) {
            throw new Error('Settlement already exists');
        }
        for (const line of batch.lines) {
            if (this.orders.has(line.orderId)) {
                throw new Error('Order has already entered a settlement');
            }
        }
        this.batches.set(batch.id,copyBatch(batch));
        for (const line of batch.lines) {
            this.orders.set(line.orderId,batch.id);
        }
        return copyBatch(batch);
    }

    get(id: string): SettlementBatch | undefined {
        const value = this.batches.get(id);
        return value && copyBatch(value);
    }

    update(batch: SettlementBatch): SettlementBatch {
        const current = this.batches.get(batch.id);
        if (!current) {
            throw new Error('Settlement not found');
        }
        if (current.accountId !== batch.accountId || JSON.stringify(current.lines) !== JSON.stringify(batch.lines)) {
            throw new Error('Settlement financial lines are immutable');
        }
        this.batches.set(batch.id,copyBatch(batch));
        return copyBatch(batch);
    }

    list(accountId?: string): SettlementBatch[] {
        return [...this.batches.values()]
            .filter(batch=>accountId===undefined || batch.accountId===accountId)
            .sort((left,right)=>right.createdAt-left.createdAt || left.id.localeCompare(right.id))
            .map(copyBatch);
    }

    forOrder(orderId: string): SettlementBatch | undefined {
        const id = this.orders.get(orderId);
        return id === undefined ? undefined : this.get(id);
    }
}

