}

export function createRoomStore(events: EventLog) {
  const rooms = new Map<string, RoomState>();

  return {
    createRoom(workspaceRoot: string, workspaceName = path.basename(workspaceRoot)) {
      const room: RoomState = {
        id: nanoid(10),
        workspaceName,
        members: [],
        connections: []
      };
      rooms.set(room.id, room);
      events.append({
        type: "room_created",
        roomId: room.id,
        payload: { workspaceName: room.workspaceName }
      });
      return room;
    },
    getRoom(roomId: string) {
      return rooms.get(roomId);
    },
    joinRoom(roomId: string, input: JoinRoomInput) {
      const room = rooms.get(roomId);
      if (!room) {
        throw new Error("Room not found");
      }

      const normalized = normalizeJoinInput(input);
      const now = new Date().toISOString();
      const existing = findExistingMember(room.members, normalized);
      if (existing) {
        existing.name = normalized.name;
        existing.participantId = normalized.participantId;
        existing.profileRole = normalized.profileRole;
        upsertConnection(room, {
          id: normalized.connectionId,
          participantId: existing.participantId,
          roomId,
          online: true,
          lastSeenAt: now
        });
        syncMemberFromConnections(room, existing, now);
        refreshDisplayNames(room);
        events.append({
          type: "member_rejoined",
          roomId,
          memberId: existing.id,
          payload: {
            name: existing.name,
            participantId: existing.participantId,
            connectionId: normalized.connectionId,
            connectionCount: existing.connectionCount
          }
        });
        return existing;
      }

      const member: RoomMember = {
        id: input.memberId ?? nanoid(10),
        participantId: normalized.participantId,
        name: normalized.name,
        displayName: normalized.name,
        online: true,
        lastSeenAt: now,
        connectionCount: 1,
        profileRole: normalized.profileRole
      };
      room.members.push(member);
      upsertConnection(room, {
        id: normalized.connectionId,
        participantId: member.participantId,
        roomId,
        online: true,
        lastSeenAt: now
      });
      refreshDisplayNames(room);
      events.append({
        type: "member_joined",
        roomId,
        memberId: member.id,
        payload: {
          name: member.name,
          participantId: member.participantId,
          connectionId: normalized.connectionId
        }
      });
      return member;
    },
    markOnline(roomId: string, memberId: string, now = new Date()) {
      const member = findMember(rooms, roomId, memberId);
      const wasOnline = member.online;
      member.online = true;
      member.lastSeenAt = now.toISOString();
      if (!wasOnline) {
        events.append({
          type: "member_online",
          roomId,
          memberId,
          payload: { name: member.displayName, lastSeenAt: member.lastSeenAt }
        });
      }
      return member;
    },
    markConnectionOnline(roomId: string, connectionId: string, now = new Date()) {
      const room = findRoom(rooms, roomId);
      const connection = room.connections.find(
        (candidate) => candidate.id === connectionId
      );
      if (!connection) {
        throw new Error("Connection not found");
      }
      const member = room.members.find(
        (candidate) => candidate.participantId === connection.participantId
      );
      if (!member) {
        throw new Error("Member not found");
      }
      const wasOnline = member.online;
      connection.online = true;
      connection.lastSeenAt = now.toISOString();
      syncMemberFromConnections(room, member, now.toISOString());
      if (!wasOnline && member.online) {
        events.append({
          type: "member_online",
          roomId,
          memberId: member.id,
          payload: {
            name: member.displayName,
            connectionId,
            lastSeenAt: member.lastSeenAt
          }
        });
      }
      return member;
    },
    markOffline(roomId: string, memberId: string, now = new Date()) {
      const member = findMember(rooms, roomId, memberId);
      const wasOnline = member.online;
      member.online = false;
      member.lastSeenAt = now.toISOString();
      if (wasOnline) {
        events.append({
          type: "member_offline",
          roomId,
          memberId,
          payload: { name: member.displayName, lastSeenAt: member.lastSeenAt }
        });
      }
      return member;
    },
    markConnectionOffline(roomId: string, connectionId: string, now = new Date()) {
      const room = findRoom(rooms, roomId);
      const connection = room.connections.find(
        (candidate) => candidate.id === connectionId
      );
      if (!connection) {
        throw new Error("Connection not found");
      }
      const member = room.members.find(
        (candidate) => candidate.participantId === connection.participantId
      );
      if (!member) {
        throw new Error("Member not found");
      }
      const wasOnline = member.online;
      connection.online = false;
      connection.lastSeenAt = now.toISOString();
      syncMemberFromConnections(room, member, now.toISOString());
      if (wasOnline && !member.online) {
        events.append({
          type: "member_offline",
          roomId,
          memberId: member.id,
          payload: {
            name: member.displayName,
            connectionId,
            lastSeenAt: member.lastSeenAt
          }
        });
      }
      return member;
    },
    cleanupStaleMembers(roomId: string, now = new Date(), ttlMs = 120_000) {
      const room = findRoom(rooms, roomId);

      const before = room.members.length;
      room.connections = room.connections.filter((connection) => {
        if (connection.online) return true;
        return now.getTime() - new Date(connection.lastSeenAt).getTime() <= ttlMs;
      });
      for (const member of room.members) {
        syncMemberFromConnections(room, member, member.lastSeenAt);
      }
      room.members = room.members.filter((member) => {
        if (member.online) return true;
        return now.getTime() - new Date(member.lastSeenAt).getTime() <= ttlMs;
      });

      if (room.members.length !== before) {
        events.append({
          type: "member_removed",
          roomId,
          payload: { removed: before - room.members.length }
        });
      }

      return room.members;
    },
    updatePresence(
      roomId: string,
      memberId: string,
      patch: Pick<RoomMember, "currentFile"> & { connectionId?: string }
    ) {
      const room = findRoom(rooms, roomId);
      const member = room.members.find(
        (candidate) => candidate.id === memberId
      );
      if (!member) {
        throw new Error("Member not found");
      }

      if (patch.connectionId) {
        const connection = room.connections.find(
          (candidate) => candidate.id === patch.connectionId
        );
        if (connection) {
          connection.currentFile = patch.currentFile;
          connection.lastSeenAt = new Date().toISOString();
        }
      }
      member.currentFile = patch.currentFile;
      return member;
    },
    getMember(roomId: string, memberId: string) {
      return rooms
        .get(roomId)
        ?.members.find((member) => member.id === memberId);
    },
    listRooms() {
      return [...rooms.values()];
    }
  };
}

export function agentEnv(env: NodeJS.ProcessEnv = process.env) {
  return buildEnvironment(env, ["DEEPSEEK_API_KEY", "DEEPSEEK_BASE_URL", "DEEPSEEK_MODEL", ...(env.SIMPLERCP_AGENT_ENV_ALLOW ?? "").split(",").map((name) => name.trim())], true);
}

export function loadConfig(
  env: NodeJS.ProcessEnv = process.env,
  repositoryRoot = defaultRepositoryRoot
): ServerConfig {
  const port = Number(env.PORT ?? 4000);
  if (!Number.isInteger(port) || port < 1 || port > 65_535) {
    throw new Error("PORT must be an integer between 1 and 65535");
  }

  const configuredDataDir = env.SIMPLERCP_DATA_DIR?.trim() || undefined;
  if (configuredDataDir && !path.isAbsolute(configuredDataDir)) {
    throw new Error("SIMPLERCP_DATA_DIR must be an absolute path");
  }

  const publicOrigin = env.SIMPLERCP_PUBLIC_URL ?? "http://127.0.0.1:5173";
  const publicUrl = new URL(publicOrigin);
  if (!["http:", "https:"].includes(publicUrl.protocol)) {
    throw new Error("SIMPLERCP_PUBLIC_URL must use http or https");
  }

  const agentBaseUrl = new URL(
    env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com/v1"
  );
  if (!["http:", "https:"].includes(agentBaseUrl.protocol)) {
    throw new Error("DEEPSEEK_BASE_URL must use http or https");
  }
  const agentModel = env.DEEPSEEK_MODEL?.trim() || "deepseek-chat";
  const openCodePort = Number(env.SIMPLERCP_OPENCODE_PORT ?? 4096);
  if (!Number.isInteger(openCodePort) || openCodePort < 1 || openCodePort > 65_535) {
    throw new Error("SIMPLERCP_OPENCODE_PORT must be an integer between 1 and 65535");
  }
  const runTimeoutMs = Number(env.SIMPLERCP_AGENT_RUN_TIMEOUT_MS ?? 600_000);
  if (!Number.isInteger(runTimeoutMs) || runTimeoutMs < 1) {
    throw new Error("SIMPLERCP_AGENT_RUN_TIMEOUT_MS must be a positive integer");
  }
  const terminalEnabled = readBoolean(
    env.SIMPLERCP_TERMINAL_ENABLED,
    "SIMPLERCP_TERMINAL_ENABLED",
    true
  );
  const fakeAgentRuntime = readBoolean(
    env.SIMPLERCP_FAKE_AGENT_RUNTIME,
    "SIMPLERCP_FAKE_AGENT_RUNTIME",
    false
  );
  const importRoots = !env.SIMPLERCP_IMPORT_ROOTS?.trim()
    ? undefined
    : env.SIMPLERCP_IMPORT_ROOTS.split(",").map((value) => value.trim()).filter(Boolean);
  if (importRoots?.some((root) => !path.isAbsolute(root))) throw new Error("SIMPLERCP_IMPORT_ROOTS must contain absolute paths");
  const dataDir = configuredDataDir ?? path.resolve(repositoryRoot, ".simplercp-data");
  const workspacesDir = env.SIMPLERCP_WORKSPACES_DIR?.trim() || path.join(dataDir, "workspaces");
  if (!path.isAbsolute(workspacesDir)) throw new Error("SIMPLERCP_WORKSPACES_DIR must be an absolute path");

  const config: ServerConfig = {
    port,
    host: env.SIMPLERCP_HOST ?? "127.0.0.1",
    publicOrigin: publicUrl.origin,
    dataDir,
    workspacesDir,
    importRoots,
    demoProjectRoot: path.resolve(repositoryRoot, "demo/workspace"),
    terminalEnabled,
    fakeAgentRuntime,
    agent: {
      apiKey: env.DEEPSEEK_API_KEY?.trim() || undefined,
      baseUrl: agentBaseUrl.toString().replace(/\/$/, ""),
      model: agentModel,
      openCodePort,
      runTimeoutMs
    }
  };
  return config;
}

export function createChatStore(
  events: EventLog,
  options: { storagePath?: string } = {}
) {
  let messages: ChatMessage[] = [];
  let operations: Promise<void> | undefined;
  const listeners = new Set<(message: ChatMessage) => void>();

  function ensureLoaded() {
    operations ??= loadMessages(options.storagePath).then((loaded) => {
      messages = loaded;
    });
    return operations;
  }

  return {
    async createMessage(input: CreateChatMessageInput) {
      let created: ChatMessage | undefined;
      const creation = ensureLoaded().then(async () => {
        const message: ChatMessage = {
          sequence: (messages.at(-1)?.sequence ?? 0) + 1,
          id: nanoid(10),
          timestamp: new Date().toISOString(),
          roomId: input.roomId,
          authorId: input.authorId,
          authorName: input.authorName,
          authorRole: input.authorRole,
          agentSessionId: input.agentSessionId,
          runId: input.runId,
          mentions: input.mentions,
          kind: input.kind ?? "member",
          text: String(redactSensitive(input.text))
        };
        const nextMessages = [...messages, message];
        await saveMessages(options.storagePath, nextMessages);
        messages = nextMessages;
        events.append({
          type: "chat_message_created",
          roomId: message.roomId,
          memberId: message.authorId,
          payload: {
            messageId: message.id,
            authorName: message.authorName,
            ...(message.authorRole ? { authorRole: message.authorRole } : {}),
            text: message.text
          }
        });
        created = message;
        for (const listener of listeners) listener(message);
      });
      operations = creation;
      await creation;
      if (!created) throw new Error("Chat message was not created");
      return created;
    },
    async listMessages(roomId: string) {
      await ensureLoaded();
      return messages.map((message) => ({ ...message, roomId }));
    },
    async updateMessage(messageId: string, update: Partial<Pick<ChatMessage, "mentions" | "agentSessionId" | "runId">>) {
      let updated: ChatMessage | undefined;
      const operation = ensureLoaded().then(async () => {
        const index = messages.findIndex((message) => message.id === messageId);
        if (index < 0) throw new Error("Chat message not found");
        const current = messages[index];
        if (!current) throw new Error("Chat message not found");
        const message: ChatMessage = { ...current, ...update };
        const nextMessages = [...messages];
        nextMessages[index] = message;
        await saveMessages(options.storagePath, nextMessages);
        messages = nextMessages;
        updated = message;
        for (const listener of listeners) listener(message);
      });
      operations = operation;
      await operation;
      if (!updated) throw new Error("Chat message was not updated");
      return updated;
    },
    onMessage(listener: (message: ChatMessage) => void) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    async awaitIdle() {
      await ensureLoaded();
    }
  };
}

export function createRecordStore<T extends { id: string; projectId: string }>(
  options: RecordStoreOptions<T>
) {
  const records = new Map<string, T>();
  let loading: Promise<void> | undefined;
  let operations = Promise.resolve();

  async function load() {
    for (const entry of await readDirectory(options.root)) {
      if (!entry.isDirectory()) continue;
      const stored = await readJsonFile<Record<string, unknown>>(
        path.join(options.root, entry.name, options.fileName)
      );
      const value = stored?.[options.recordKey];
      if (
        stored?.version !== 1 ||
        !options.validateRecord(value) ||
        value.projectId !== options.projectId ||
        value.id !== entry.name
      ) {
        throw new Error(options.invalidMessage);
      }
      records.set(value.id, value);
    }
  }

  function ensureLoaded() {
    loading ??= load();
    return loading;
  }

  function enqueue<R>(operation: () => Promise<R>): Promise<R> {
    const result = operations.then(operation);
    operations = result.then(() => undefined, () => undefined);
    return result;
  }

  async function save(record: T) {
    await writeJsonFileAtomically(
      path.join(options.root, record.id, options.fileName),
      { version: 1, [options.recordKey]: record }
    );
  }

  return {
    async create(record: T) {
      await ensureLoaded();
      return enqueue(async () => {
        if (records.has(record.id)) throw new Error(options.invalidMessage);
        await save(record);
        records.set(record.id, record);
        return { ...record };
      });
    },
    async get(id: string) {
      await ensureLoaded();
      await operations;
      const record = records.get(id);
      return record ? { ...record } : undefined;
    },
    async list() {
      await ensureLoaded();
      await operations;
      return [...records.values()].map((record) => ({ ...record }));
    },
    async update(id: string, change: (current: T) => T) {
      await ensureLoaded();
      return enqueue(async () => {
        const current = records.get(id);
        if (!current) throw new Error(options.missingMessage);
        const next = change(current);
        if (next.id !== id || next.projectId !== options.projectId) {
          throw new Error(options.invalidMessage);
        }
        await save(next);
        records.set(id, next);
        return { ...next };
      });
    }
  };
}

export function createRoomStore(events: EventLog) {
  const rooms = new Map<string, RoomState>();

  return {
    createRoom(workspaceRoot: string, workspaceName = path.basename(workspaceRoot)) {
      const room: RoomState = {
        id: nanoid(10),
        workspaceName,
        members: [],
        connections: []
      };
      rooms.set(room.id, room);
      events.append({
        type: "room_created",
        roomId: room.id,
        payload: { workspaceName: room.workspaceName }
      });
      return room;
    },
    getRoom(roomId: string) {
      return rooms.get(roomId);
    },
    joinRoom(roomId: string, input: JoinRoomInput) {
      const room = rooms.get(roomId);
      if (!room) {
        throw new Error("Room not found");
      }

      const normalized = normalizeJoinInput(input);
      const now = new Date().toISOString();
      const existing = findExistingMember(room.members, normalized);
      if (existing) {
        existing.name = normalized.name;
        existing.participantId = normalized.participantId;
        existing.profileRole = normalized.profileRole;
        upsertConnection(room, {
          id: normalized.connectionId,
          participantId: existing.participantId,
          roomId,
          online: true,
          lastSeenAt: now
        });
        syncMemberFromConnections(room, existing, now);
        refreshDisplayNames(room);
        events.append({
          type: "member_rejoined",
          roomId,
          memberId: existing.id,
          payload: {
            name: existing.name,
            participantId: existing.participantId,
            connectionId: normalized.connectionId,
            connectionCount: existing.connectionCount
          }
        });
        return existing;
      }

      const member: RoomMember = {
        id: input.memberId ?? nanoid(10),
        participantId: normalized.participantId,
        name: normalized.name,
        displayName: normalized.name,
        online: true,
        lastSeenAt: now,
        connectionCount: 1,
        profileRole: normalized.profileRole
      };
      room.members.push(member);
      upsertConnection(room, {
        id: normalized.connectionId,
        participantId: member.participantId,
        roomId,
        online: true,
        lastSeenAt: now
      });
      refreshDisplayNames(room);
      events.append({
        type: "member_joined",
        roomId,
        memberId: member.id,
        payload: {
          name: member.name,
          participantId: member.participantId,
          connectionId: normalized.connectionId
        }
      });
      return member;
    },
    markOnline(roomId: string, memberId: string, now = new Date()) {
      const member = findMember(rooms, roomId, memberId);
      const wasOnline = member.online;
      member.online = true;
      member.lastSeenAt = now.toISOString();
      if (!wasOnline) {
        events.append({
          type: "member_online",
          roomId,
          memberId,
          payload: { name: member.displayName, lastSeenAt: member.lastSeenAt }
        });
      }
      return member;
    },
    markConnectionOnline(roomId: string, connectionId: string, now = new Date()) {
      const room = findRoom(rooms, roomId);
      const connection = room.connections.find(
        (candidate) => candidate.id === connectionId
      );
      if (!connection) {
        throw new Error("Connection not found");
      }
      const member = room.members.find(
        (candidate) => candidate.participantId === connection.participantId
      );
      if (!member) {
        throw new Error("Member not found");
      }
      const wasOnline = member.online;
      connection.online = true;
      connection.lastSeenAt = now.toISOString();
      syncMemberFromConnections(room, member, now.toISOString());
      if (!wasOnline && member.online) {
        events.append({
          type: "member_online",
          roomId,
          memberId: member.id,
          payload: {
            name: member.displayName,
            connectionId,
            lastSeenAt: member.lastSeenAt
          }
        });
      }
      return member;
    },
    markOffline(roomId: string, memberId: string, now = new Date()) {
      const member = findMember(rooms, roomId, memberId);
      const wasOnline = member.online;
      member.online = false;
      member.lastSeenAt = now.toISOString();
      if (wasOnline) {
        events.append({
          type: "member_offline",
          roomId,
          memberId,
          payload: { name: member.displayName, lastSeenAt: member.lastSeenAt }
        });
      }
      return member;
    },
    markConnectionOffline(roomId: string, connectionId: string, now = new Date()) {
      const room = findRoom(rooms, roomId);
      const connection = room.connections.find(
        (candidate) => candidate.id === connectionId
      );
      if (!connection) {
        throw new Error("Connection not found");
      }
      const member = room.members.find(
        (candidate) => candidate.participantId === connection.participantId
      );
      if (!member) {
        throw new Error("Member not found");
      }
      const wasOnline = member.online;
      connection.online = false;
      connection.lastSeenAt = now.toISOString();
      syncMemberFromConnections(room, member, now.toISOString());
      if (wasOnline && !member.online) {
        events.append({
          type: "member_offline",
          roomId,
          memberId: member.id,
          payload: {
            name: member.displayName,
            connectionId,
            lastSeenAt: member.lastSeenAt
          }
        });
      }
      return member;
    },
    cleanupStaleMembers(roomId: string, now = new Date(), ttlMs = 120_000) {
      const room = findRoom(rooms, roomId);

      const before = room.members.length;
      room.connections = room.connections.filter((connection) => {
        if (connection.online) return true;
        return now.getTime() - new Date(connection.lastSeenAt).getTime() <= ttlMs;
      });
      for (const member of room.members) {
        syncMemberFromConnections(room, member, member.lastSeenAt);
      }
      room.members = room.members.filter((member) => {
        if (member.online) return true;
        return now.getTime() - new Date(member.lastSeenAt).getTime() <= ttlMs;
      });

      if (room.members.length !== before) {
        events.append({
          type: "member_removed",
          roomId,
          payload: { removed: before - room.members.length }
        });
      }

      return room.members;
    },
    updatePresence(
      roomId: string,
      memberId: string,
      patch: Pick<RoomMember, "currentFile"> & { connectionId?: string }
    ) {
      const room = findRoom(rooms, roomId);
      const member = room.members.find(
        (candidate) => candidate.id === memberId
      );
      if (!member) {
        throw new Error("Member not found");
      }

      if (patch.connectionId) {
        const connection = room.connections.find(
          (candidate) => candidate.id === patch.connectionId
        );
        if (connection) {
          connection.currentFile = patch.currentFile;
          connection.lastSeenAt = new Date().toISOString();
        }
      }
      member.currentFile = patch.currentFile;
      return member;
    },
    getMember(roomId: string, memberId: string) {
      return rooms
        .get(roomId)
        ?.members.find((member) => member.id === memberId);
    },
    listRooms() {
      return [...rooms.values()];
    }
  };
}

export async function createAgentWorkspaceSnapshot(
  workspacePath: string
): Promise<AgentWorkspaceSnapshot> {
  const snapshot: AgentWorkspaceSnapshot = new Map();
  await readDirectory(workspacePath, "", snapshot);
  return snapshot;
}

export function compareAgentWorkspaceSnapshots(
  before: AgentWorkspaceSnapshot,
  after: AgentWorkspaceSnapshot
): AgentFileChange[] {
  const paths = new Set([...before.keys(), ...after.keys()]);
  const changes: AgentFileChange[] = [];
  for (const file of [...paths].sort((left, right) => left.localeCompare(right))) {
    const previous = before.get(file);
    const current = after.get(file);
    if (previous && current && previous.bytes.equals(current.bytes)) continue;
    if (!previous && current) {
      changes.push({
        file,
        additions: current.content === undefined ? 0 : countLines(current.content),
        deletions: 0,
        status: "added"
      });
      continue;
    }
    if (previous && !current) {
      changes.push({
        file,
        additions: 0,
        deletions: previous.content === undefined ? 0 : countLines(previous.content),
        status: "deleted"
      });
      continue;
    }
    const counts = countTextChanges(previous?.content, current?.content);
    changes.push({
      file,
      additions: counts.additions,
      deletions: counts.deletions,
      status: "modified"
    });
  }
  return changes;
}

export function createAgentRunStore(projectId: string, projectRoot: string) {
  const runsRoot = path.join(projectRoot, "agent-runs");
  const records = createRecordStore<AgentRun>({
    root: runsRoot,
    projectId,
    fileName: "run.json",
    recordKey: "run",
    invalidMessage: "Invalid Agent run file",
    missingMessage: "Agent run not found",
    validateRecord(value): value is AgentRun {
      if (!value || typeof value !== "object") return false;
      const run = value as Record<string, unknown>;
      return typeof run.id === "string" && typeof run.projectId === "string";
    }
  });

  return {
    runsRoot,
    create(input: Omit<AgentRun, "id" | "createdAt">, id = nanoid(12)) {
      return records.create({
        ...input,
        id,
        createdAt: new Date().toISOString()
      });
    },
    get: records.get,
    async list() {
      return (await records.list()).sort((left, right) =>
        right.createdAt.localeCompare(left.createdAt)
      );
    },
    update(runId: string, update: Partial<AgentRun>) {
      return records.update(runId, (current) => ({ ...current, ...update, id: current.id }));
    }
  };
}

export async function buildRuntimePrompt(
  workspacePath: string,
  prompt: string,
  contexts: AgentPromptContext[] | undefined,
  projectName: string
) {
  const scope = [
    `You are working only on the project "${projectName}".`,
    `The project workspace is ${workspacePath}.`,
    "Use only files inside this workspace as project context.",
    "Do not inspect, describe, or use any parent directory or parent repository."
  ].join("\n");
  if (!contexts || contexts.length === 0) return `${scope}\n\nUser request:\n${prompt}`;
  const sections: string[] = [];
  for (const context of contexts) {
    const result = await readWorkspaceFile(workspacePath, context.path);
    if (result.status !== "text") {
      throw new Error(
        `Agent context must be a text file smaller than 1 MB: ${context.path}`
      );
    }
    sections.push(
      `--- ${context.path} ---\n${result.content}\n--- end ${context.path} ---`
    );
  }
  return `${scope}\n\nRelevant project files:\n${sections.join("\n")}\n\nUser request:\n${prompt}`;
}

export function previewPrompt(prompt: string) {
  const normalized = prompt.replace(/\s+/g, " ").trim();
  return normalized.length > 120 ? `${normalized.slice(0, 117)}…` : normalized;
}

