  prepareRun?(input: { workspacePath: string; sessionId: string; runPrompt: string }): Promise<void>;
  createSession(input: {
    workspacePath: string;
    title: string;
  }): Promise<{ id: string }>;
  run(input: {
    workspacePath: string;
    sessionId: string;
    prompt: string;
  }): Promise<{ text: string; messageId?: string }>;
  getDiff(input: {
    workspacePath: string;
    sessionId: string;
    messageId?: string;
  }): Promise<AgentFileChange[]>;
  cancel(input: {
    workspacePath: string;
    sessionId: string;
  }): Promise<void>;
  subscribe(
    input: { workspacePath: string; sessionId: string },
    listener: (event: AgentRuntimeEvent) => void | Promise<void>
  ): Promise<() => Promise<void>>;
  dispose(): Promise<void>;
}

export function normalizeHandle(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 32);
}

export function validateHandle(handle: string) {
  if (!HANDLE_PATTERN.test(handle) || RESERVED_HANDLES.has(handle)) {
    throw new Error("Team Agent handle must use 1-32 lowercase letters, numbers, or hyphens");
  }
  return handle;
}

export function normalizeAgentContexts(
  contexts: AgentPromptContext[] | undefined
) {
  if (!contexts) return undefined;
  if (!Array.isArray(contexts)) {
    throw new Error("Agent contexts must be an array");
  }
  const normalized = contexts.map((context) => {
    if (
      context?.type !== "file" ||
      typeof context.path !== "string" ||
      !context.path.trim()
    ) {
      throw new Error("Invalid Agent file context");
    }
    return { type: "file" as const, path: context.path.trim() };
  });
  return normalized.length ? normalized : undefined;
}

export async function runWithTimeout<T>(
  operation: Promise<T>,
  timeoutMs: number,
  cancel: () => Promise<void>
) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let cancellation: Promise<void> | undefined;
  const timeout = new Promise<never>((_resolve, reject) => {
    timer = setTimeout(() => {
      cancellation = cancel();
      reject(new Error(`Agent run exceeded ${timeoutMs} ms`));
    }, timeoutMs);
  });
  try {
    return await Promise.race([operation, timeout]);
  } catch (error) {
    if (cancellation) await cancellation;
    throw error;
  } finally {
    if (timer) clearTimeout(timer);
  }
}

export function mergeFileChanges(
  workspaceChanges: AgentRun["fileChanges"] = [],
  runtimeChanges: AgentRun["fileChanges"] = []
) {
  const runtimeByFile = new Map(
    runtimeChanges.map((change) => [change.file, change])
  );
  const merged: AgentFileChange[] = workspaceChanges.map((change) => ({
    ...change,
    patch: runtimeByFile.get(change.file)?.patch
  }));
  const workspacePaths = new Set(workspaceChanges.map((change) => change.file));
  merged.push(
    ...runtimeChanges.filter((change) => !workspacePaths.has(change.file))
  );
  return merged;
}

export async function buildRuntimePrompt(
  workspacePath: string,
  prompt: string,
  contexts: AgentPromptContext[] | undefined,
  projectName: string
) {
  const scope = [
    `You are working only on the project "${projectName}".`,
    `The project workspace is ${workspacePath}.`,
    "Use only files inside this workspace as project context.",
    "Do not inspect, describe, or use any parent directory or parent repository."
  ].join("\n");
  if (!contexts || contexts.length === 0) return `${scope}\n\nUser request:\n${prompt}`;
  const sections: string[] = [];
  for (const context of contexts) {
    const result = await readWorkspaceFile(workspacePath, context.path);
    if (result.status !== "text") {
      throw new Error(
        `Agent context must be a text file smaller than 1 MB: ${context.path}`
      );
    }
    sections.push(
      `--- ${context.path} ---\n${result.content}\n--- end ${context.path} ---`
    );
  }
  return `${scope}\n\nRelevant project files:\n${sections.join("\n")}\n\nUser request:\n${prompt}`;
}

async function load() {
    for (const entry of await readDirectory(options.root)) {
      if (!entry.isDirectory()) continue;
      const stored = await readJsonFile<Record<string, unknown>>(
        path.join(options.root, entry.name, options.fileName)
      );
      const value = stored?.[options.recordKey];
      if (
        stored?.version !== 1 ||
        !options.validateRecord(value) ||
        value.projectId !== options.projectId ||
        value.id !== entry.name
      ) {
        throw new Error(options.invalidMessage);
      }
      records.set(value.id, value);
    }
  }

function ensureLoaded() {
    loading ??= load();
    return loading;
  }

function enqueue<R>(operation: () => Promise<R>): Promise<R> {
    const result = operations.then(operation);
    operations = result.then(() => undefined, () => undefined);
    return result;
  }

export function parseMentions(text: string, candidates: Set<string>) {
  const mentions: string[] = [];
  const seen = new Set<string>();
  const pattern = /(^|[^\p{L}\p{N}._%+\-])@([a-z0-9][a-z0-9-]{0,31})\b/giu;
  for (const match of text.matchAll(pattern)) {
    const handle = match[2]?.toLowerCase();
    if (!handle || !candidates.has(handle) || seen.has(handle)) continue;
    seen.add(handle);
    mentions.push(handle);
  }
  return mentions;
}

async function readDirectory(directoryPath: string) {
  try {
    return await fs.readdir(directoryPath, { withFileTypes: true });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }
}

export async function migrateLegacyAgentSessions(
  projectId: string,
  runStore: AgentRunStore,
  sessionStore: AgentSessionStore,
  memberIds: Set<string>
) {
  for (const session of await sessionStore.list()) {
    if ((session.scope ?? "personal") !== "team" && !memberIds.has(session.memberId) && !session.historical) {
      await sessionStore.update(session.id, { historical: true });
    }
  }
  const runs = await runStore.list();
  const migrated = new Map<
    string,
    Awaited<ReturnType<typeof sessionStore.create>>
  >();

  for (const run of runs) {
    if (run.sessionId && await sessionStore.get(run.sessionId)) continue;
    const legacyRuntimeSessionId = run.runtimeSessionId ?? run.sessionId;
    const migrationKey = `${run.memberId}:${legacyRuntimeSessionId ?? run.id}`;
    let session = migrated.get(migrationKey);
    if (!session) {
      session = await sessionStore.create({
        projectId,
        memberId: run.memberId,
        memberName: run.memberName,
        historical: !memberIds.has(run.memberId),
        title: run.prompt.slice(0, 80),
        runtime: "opencode",
        runtimeSessionId: legacyRuntimeSessionId,
        lastRunId: run.id
      });
      migrated.set(migrationKey, session);
    }
    await runStore.update(run.id, {
      sessionId: session.id,
      runtimeSessionId: legacyRuntimeSessionId
    });
  }
}

