export async function createAgentSettingsStore(
  options: AgentSettingsStoreOptions
) {
  let settings = await loadSettings(options.storagePath, options.defaultModel);
  let operations = Promise.resolve();

  function get(): AgentSettingsResponse {
    return { ...settings, apiKeyConfigured: options.apiKeyConfigured };
  }

  return {
    get,
    async update(input: unknown): Promise<AgentSettingsResponse> {
      const nextSettings = validateSettings(input);
      operations = operations.then(async () => {
        await saveSettings(options.storagePath, nextSettings);
        settings = nextSettings;
      });
      await operations;
      return get();
    }
  };
}

function get(): AgentSettingsResponse {
    return { ...settings, apiKeyConfigured: options.apiKeyConfigured };
  }

export async function readJsonFile<T>(storagePath: string): Promise<T | undefined> {
  try {
    return JSON.parse(await fs.readFile(storagePath, "utf8")) as T;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
    throw error;
  }
}

async function loadSettings(
  storagePath: string,
  defaultModel: string
): Promise<AgentSettings> {
  const parsed = await readJsonFile<AgentSettingsFile>(storagePath);
  if (parsed === undefined) {
    return { provider: "deepseek", model: defaultModel, enabled: true };
  }
  validateSettingsFile(parsed);
  return parsed.settings;
}

function buildEnvironment(env: NodeJS.ProcessEnv, additional: string[], agent: boolean) {
  const allowed = new Set([...baseNames, ...additional]);
  const entries = Object.entries(env).filter(([name, value]) => {
    if (typeof value !== "string" || identityNames.test(name)) return false;
    if (sensitiveNames.test(name) && !(agent && name === "DEEPSEEK_API_KEY")) return false;
    return allowed.has(name) || name.startsWith("LC_");
  });
  const result = Object.fromEntries(entries) as Record<string, string>;
  if (env.SIMPLERCP_TERMINAL_HOME) result.HOME = env.SIMPLERCP_TERMINAL_HOME;
  return result;
}

export async function createProjectRegistry({
  dataDir,
  workspacesDir,
  importRoots,
  demoProjectRoot
}: {
  dataDir: string;
  workspacesDir?: string;
  importRoots?: string[];
  demoProjectRoot: string;
}) {
  const projectsDir = path.join(dataDir, "projects");
  const workspacesRoot = workspacesDir ?? path.join(dataDir, "workspaces");
  const registryPath = path.join(dataDir, "registry.json");
  await fs.mkdir(projectsDir, { recursive: true, mode: 0o700 });
  await fs.mkdir(workspacesRoot, { recursive: true, mode: 0o700 });

  let registry = await loadRegistry(registryPath);
  registry = await migrateLegacyProjects(registry, { projectsDir, workspacesDir: workspacesRoot, dataDir, registryPath });
  if (!registry.projects.some((project) => project.id === "demo")) {
    const project = await createDemoProject({ projectsDir, workspacesDir: workspacesRoot, demoProjectRoot });
    registry = { ...registry, projects: [...registry.projects, project] };
    await saveRegistry(registryPath, registry);
  }

  return {
    listProjectsSync() {
      return [...registry.projects];
    },
    async listProjects() {
      const missingProjectIds = new Set<string>();
      let recreatedDemo: ProjectRecord | undefined;
      for (const project of registry.projects) {
        if (await pathExists(project.workspacePath)) continue;
        if (project.id === "demo") {
          recreatedDemo = await createDemoProject({ projectsDir, workspacesDir: workspacesRoot, demoProjectRoot });
        } else {
          missingProjectIds.add(project.id);
        }
      }
      if (missingProjectIds.size > 0 || recreatedDemo) {
        registry = {
          ...registry,
          projects: registry.projects.flatMap((project) => {
            if (missingProjectIds.has(project.id)) return [];
            if (project.id === "demo" && recreatedDemo) return [recreatedDemo];
            return [project];
          })
        };
        await saveRegistry(registryPath, registry);
      }
      return [...registry.projects].sort((left, right) =>
        right.lastOpenedAt.localeCompare(left.lastOpenedAt)
      );
    },
    getProject(projectId: string) {
      return registry.projects.find((project) => project.id === projectId);
    },
    async createBlankProject(name: string) {
      const normalizedName = validateProjectName(name, registry.projects);
      const id = nanoid(12);
      const projectDir = path.join(projectsDir, id);
      const workspacePath = path.join(workspacesRoot, id);
      await fs.mkdir(workspacePath, { recursive: true, mode: 0o700 });
      const timestamp = new Date().toISOString();
      const project: ProjectRecord = {
        id,
        name: normalizedName,
        source: "blank",
        workspacePath,
        metadataPath: projectDir,
        createdAt: timestamp,
        lastOpenedAt: timestamp
      };
      await writeProjectMetadata(projectDir, project);
      registry = { ...registry, projects: [...registry.projects, project] };
      await saveRegistry(registryPath, registry);
      return project;
    },

async function loadRegistry(registryPath: string): Promise<RegistryFile> {
  const parsed = await readJsonFile<RegistryFile>(registryPath);
  if (parsed === undefined) return { version: 1, projects: [] };
  if (!parsed || parsed.version !== 1 || !Array.isArray(parsed.projects)) {
    throw new Error("Invalid project registry");
  }
  return parsed;
}

async function createDemoProject({
  projectsDir,
  workspacesDir,
  demoProjectRoot
}: {
  projectsDir: string;
  workspacesDir: string;
  demoProjectRoot: string;
}): Promise<ProjectRecord> {
  const projectDir = path.join(projectsDir, "demo");
  const workspacePath = path.join(workspacesDir, "demo");
  if (!(await pathExists(workspacePath))) {
    await fs.mkdir(projectDir, { recursive: true, mode: 0o700 });
    await fs.cp(demoProjectRoot, workspacePath, { recursive: true });
  }
  const timestamp = new Date().toISOString();
  const project: ProjectRecord = {
    id: "demo",
    name: "Demo",
    source: "demo",
    workspacePath,
    metadataPath: projectDir,
    createdAt: timestamp,
    lastOpenedAt: timestamp
  };
  await writeProjectMetadata(projectDir, project);
  return project;
}

async function migrateLegacyProjects(registry: RegistryFile, options: { projectsDir: string; workspacesDir: string; dataDir: string; registryPath: string }) {
  const markerDir = path.join(options.dataDir, "instance");
  await fs.mkdir(markerDir, { recursive: true, mode: 0o700 });
  const migrated: ProjectRecord[] = [];
  const completed: string[] = [];
  for (const project of registry.projects) {
    if (project.metadataPath) {
      if (await pathExists(path.join(markerDir, `migration-${project.id}.started`)) && await pathExists(project.workspacePath)) completed.push(project.id);
      migrated.push(project);
      continue;
    }
    const metadataPath = project.metadataPath ?? path.dirname(project.workspacePath);
    const legacyWorkspace = path.join(metadataPath, "workspace");
    const nextWorkspace = path.join(options.workspacesDir, project.id);
    const copiedMarker = path.join(markerDir, `migration-${project.id}.copied.json`);
    await fs.writeFile(path.join(markerDir, `migration-${project.id}.started`), new Date().toISOString());
    const sourceExists = await pathExists(legacyWorkspace);
    const destinationExists = await pathExists(nextWorkspace);
    if (sourceExists && destinationExists) {
      const copied = await readJsonFile<{ source: string; destination: string }>(copiedMarker);
      if (copied?.source !== legacyWorkspace || copied.destination !== nextWorkspace) throw new Error("Migration destination already exists");
      await fs.rm(legacyWorkspace, { recursive: true });
    } else if (sourceExists) {
      try {
        await fs.rename(legacyWorkspace, nextWorkspace);
      } catch (error) {
        if (!(error instanceof Error && "code" in error && error.code === "EXDEV")) throw error;
        const stagingPath = `${nextWorkspace}.migration`;
        await fs.rm(stagingPath, { recursive: true, force: true });
        await fs.cp(legacyWorkspace, stagingPath, { recursive: true, preserveTimestamps: true });
        await writeJsonFileAtomically(copiedMarker, { source: legacyWorkspace, destination: nextWorkspace });
        await fs.rename(stagingPath, nextWorkspace);
        await fs.rm(legacyWorkspace, { recursive: true });
      }
    }
    const updated = { ...project, metadataPath, workspacePath: nextWorkspace };
    await writeProjectMetadata(metadataPath, updated);
    migrated.push(updated);
    completed.push(project.id);
  }
  const next = { ...registry, projects: migrated };
  if (JSON.stringify(next) !== JSON.stringify(registry)) await saveRegistry(options.registryPath, next);
  for (const projectId of completed) {
    await fs.writeFile(path.join(markerDir, `migration-${projectId}.complete`), new Date().toISOString());
  }
  return next;
}

export function getProjectMetadataPath(project: ProjectRecord) {
  if (!project.metadataPath) throw new Error("Project metadata path is required");
  return project.metadataPath;
}

function validateSettingsFile(value: AgentSettingsFile) {
  if (
    !value ||
    value.version !== 1 ||
    value.settings?.provider !== "deepseek" ||
    typeof value.settings.model !== "string" ||
    !value.settings.model.trim() ||
    typeof value.settings.enabled !== "boolean"
  ) {
    throw new Error("Invalid Agent settings file");
  }
}

export function registerProjectRoutes(
  app: Express,
  dependencies: {
    agentRuns: AgentRunManager;
    registry: ProjectRegistry;
    runtimeManager: ProjectRuntimeManager;
  }
) {
  const { agentRuns, registry, runtimeManager } = dependencies;

  app.get("/api/projects", async (_req, res, next) => {
    try {
      const projects = await registry.listProjects();
      const projectIds = new Set(projects.map((project) => project.id));
      await Promise.all(runtimeManager.listActive().filter((runtime) => !projectIds.has(runtime.project.id)).map((runtime) => runtimeManager.disposeProject(runtime.project.id)));
      res.json({ projects });
    } catch (error) {
      next(error);
    }
  });

  app.post("/api/projects", async (req, res, next) => {
    try {
      if (!can(req.identity, "project:write")) { res.sendStatus(403); return; }
      const project = await registry.createBlankProject(String(req.body?.name ?? ""));
      res.status(201).json({ project });
    } catch (error) {
      next(error);
    }
  });

  app.post("/api/projects/import", async (req, res, next) => {
    try {
      if (!can(req.identity, "project:write")) { res.sendStatus(403); return; }
      const project = await registry.importDirectory(String(req.body?.name ?? ""), String(req.body?.path ?? ""));
      res.status(201).json({ project });
    } catch (error) {
      next(error);
    }
  });

  app.post("/api/projects/import-zip", express.raw({ type: "application/zip", limit: "200mb" }), async (req, res, next) => {
    try {
      if (!can(req.identity, "project:write")) { res.sendStatus(403); return; }
      if (!Buffer.isBuffer(req.body)) {
        res.status(400).json({ error: "A ZIP archive is required" });
        return;
      }
      res.status(201).json(await registry.importZip(String(req.query.name ?? ""), req.body));
    } catch (error) {
      next(error);
    }
  });

  app.get("/api/projects/:projectId", async (req, res, next) => {
    try {
      const project = await registry.markOpened(req.params.projectId);
      const runtime = runtimeManager.get(project.id);
      res.json({ project, roomId: runtime.room.id });
    } catch (error) {
      next(error);
    }
  });

  app.delete("/api/projects/:projectId", async (req, res, next) => {
    try {
      if (!can(req.identity, "project:write", { projectId: req.params.projectId })) { res.sendStatus(403); return; }
      const projectId = req.params.projectId;
      const project = registry.getProject(projectId);
      if (!project) throw new Error("Project not found");
      if (project.source === "demo") throw new Error("Demo project cannot be deleted");
      await agentRuns.disposeProject(projectId);
      await runtimeManager.disposeProject(projectId);
      await registry.deleteProject(projectId);
      res.json({ deletedProjectId: projectId });
    } catch (error) {
      next(error);
    }
  });
}

function validateProjectName(name: string, projects: ProjectRecord[]) {
  const normalized = name.trim();
  if (!normalized) throw new Error("Project name is required");
  if (normalized.length > 100) {
    throw new Error("Project name must be at most 100 characters");
  }
  if (
    projects.some(
      (project) => project.name.toLowerCase() === normalized.toLowerCase()
    )
  ) {
    throw new Error("A project with this name already exists");
  }
  return normalized;
}

function normalizeJoinInput(input: JoinRoomInput): NormalizedJoinInput {
  const participantId =
    input.participantId ?? input.connectionId ?? `human:${input.name}`;
  return {
    name: input.name,
    participantId,
    connectionId: input.connectionId ?? participantId,
    profileRole: input.profileRole
  };
}

function findExistingMember(members: RoomMember[], input: NormalizedJoinInput) {
  return members.find(
    (member) => member.participantId === input.participantId
  );
}

function upsertConnection(room: RoomState, connection: RoomConnection) {
  const existing = room.connections.find(
    (candidate) => candidate.id === connection.id
  );
  if (existing) {
    Object.assign(existing, connection);
    return existing;
  }
  room.connections.push(connection);
  return connection;
}

function syncMemberFromConnections(
  room: RoomState,
  member: RoomMember,
  fallbackLastSeenAt: string
) {
  const connections = room.connections.filter(
    (connection) => connection.participantId === member.participantId
  );
  const onlineConnections = connections.filter((connection) => connection.online);
  member.connectionCount = onlineConnections.length;
  member.online = onlineConnections.length > 0;
  member.lastSeenAt =
    connections
      .map((connection) => connection.lastSeenAt)
      .sort()
      .at(-1) ?? fallbackLastSeenAt;
  member.currentFile =
    onlineConnections.find((connection) => connection.currentFile)?.currentFile ??
    member.currentFile;
}

function refreshDisplayNames(room: RoomState) {
  const counts = new Map<string, number>();
  for (const member of room.members) {
    const count = (counts.get(member.name) ?? 0) + 1;
    counts.set(member.name, count);
    member.displayName = count === 1 ? member.name : `${member.name} #${count}`;
  }
}

function get(): AgentSettingsResponse {
    return { ...settings, apiKeyConfigured: options.apiKeyConfigured };
  }

function findMember(
  rooms: Map<string, RoomState>,
  roomId: string,
  memberId: string
) {
  const room = findRoom(rooms, roomId);
  const member = room.members.find((candidate) => candidate.id === memberId);
  if (!member) {
    throw new Error("Member not found");
  }
  return member;
}

